"use client";
import { scrollAreaListChildren } from "@/components/ui/scroll-area";

import * as React from "react";
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import { cva } from "class-variance-authority";
import { cn } from "@/lib/utils";
import * as Primitive from "@radix-ui/react-context-menu";
import {
  useFlowAppearance,
  useFlowGroup,
} from "@/lib/sahajiv-motion/use-flow";

import { adornItem, itemText, type ItemAdornmentItemProps } from "@/components/ui/item-adornment";
import { StateChevron, AnimatedIcon } from "@/components/ui/animated-icon";

export type ContextMenuProps = React.ComponentProps<typeof Primitive.Root>;
export function ContextMenu(props: ContextMenuProps) {
  return <Primitive.Root {...props} />;
}
export type ContextMenuPortalProps = React.ComponentProps<
  typeof Primitive.Portal
>;
export function ContextMenuPortal(props: ContextMenuPortalProps) {
  return <Primitive.Portal {...props} />;
}
export type ContextMenuGroupProps = React.ComponentProps<
  typeof Primitive.Group
>;
export function ContextMenuGroup(props: ContextMenuGroupProps) {
  return <Primitive.Group data-slot="context-menu-group" {...props} />;
}
export type ContextMenuRadioGroupProps = React.ComponentProps<
  typeof Primitive.RadioGroup
>;
export function ContextMenuRadioGroup(props: ContextMenuRadioGroupProps) {
  return (
    <Primitive.RadioGroup data-slot="context-menu-radiogroup" {...props} />
  );
}
export type ContextMenuSubProps = React.ComponentProps<typeof Primitive.Sub>;
export function ContextMenuSub(props: ContextMenuSubProps) {
  return <Primitive.Sub {...props} />;
}
export type ContextMenuTriggerProps = React.ComponentProps<
  typeof Primitive.Trigger
>;
export function ContextMenuTrigger({
  className,
  ref,
  onKeyDown,
  ...props
}: ContextMenuTriggerProps) {
  return (
    <Primitive.Trigger
      ref={ref}
      data-slot="context-menu-trigger"
      data-part="trigger"
      data-context=""
      tabIndex={0}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (event.defaultPrevented || props.disabled) return;
        if (
          event.key === "ContextMenu" ||
          (event.shiftKey && event.key === "F10")
        ) {
          event.preventDefault();
          const rect = event.currentTarget.getBoundingClientRect();
          event.currentTarget.dispatchEvent(
            new MouseEvent("contextmenu", {
              bubbles: true,
              cancelable: true,
              clientX: rect.left + rect.width / 2,
              clientY: rect.top + rect.height / 2,
            }),
          );
        }
      }}
      className={cn("", className)}
      {...props}
    />
  );
}
export const contextmenuContentVariants = cva(
  "v-menu [background:var(--popover)] [border-radius:var(--r-card-sm)] [padding:var(--s-2)] [min-width:200px] [box-shadow:var(--shadow-float)] [border:1px_solid_var(--v-border)] [display:grid] [gap:2px]",
);
export type ContextMenuContentProps = React.ComponentProps<
  typeof Primitive.Content
>;
export function ContextMenuContent({
  className,
  ref,
  children,
  ...props
}: ContextMenuContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.Content
        ref={flowRef}
        data-slot="context-menu-content"
        data-part="content"
        className={cn(contextmenuContentVariants(), className)}
        {...props}
      >
        {scrollAreaListChildren(children, props.asChild)}
      </Primitive.Content>
    </Primitive.Portal>
  );
}
export type ContextMenuSubContentProps = React.ComponentProps<
  typeof Primitive.SubContent
>;
export function ContextMenuSubContent({
  className,
  children,
  ref,
  ...props
}: ContextMenuSubContentProps) {
  const morphRef = useMorph<HTMLDivElement>("surfaces", ref);
  const groupRef = useFlowGroup<HTMLDivElement>(morphRef, {
    itemSelector: ".v-menu__item",
    activeSelector: "[data-highlighted]",
  });
  const flowRef = useFlowAppearance<HTMLDivElement>(true, groupRef, "grow");
  return (
    <Primitive.Portal>
      <Primitive.SubContent
        ref={flowRef}
        data-slot="context-menu-sub-content"
        data-part="content"
        className={cn(contextmenuContentVariants(), className)}
        {...props}
      >{scrollAreaListChildren(children, props.asChild)}</Primitive.SubContent>
    </Primitive.Portal>
  );
}
export type ContextMenuItemProps = React.ComponentProps<
  typeof Primitive.Item
> & { variant?: "default" | "danger"; inset?: boolean } & ItemAdornmentItemProps;
export function ContextMenuItem({
  className,
  children,
  adornment,
  adornmentId,
  variant,
  inset,
  ref,
  ...props
}: ContextMenuItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.Item
      ref={morphRef}
      data-slot="context-menu-item"
      data-part="item"
      data-inset={inset || undefined}
      className={cn(
        "v-menu__item flex items-center gap-[var(--s-3)] min-h-10 px-[var(--s-3)] rounded-[var(--r-md)] text-[length:var(--fs-control)] w-full text-left whitespace-nowrap outline-none",
        variant === "danger" && "-danger",
        className,
      )}
      {...props}
    >{adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild)}</Primitive.Item>
  );
}
export type ContextMenuSubTriggerProps = React.ComponentProps<
  typeof Primitive.SubTrigger
> & { inset?: boolean } & ItemAdornmentItemProps;
export function ContextMenuSubTrigger({
  className,
  adornment,
  adornmentId,
  inset,
  children,
  ref,
  ...props
}: ContextMenuSubTriggerProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.SubTrigger
      ref={morphRef}
      data-slot="context-menu-sub-trigger"
      data-part="item"
      data-inset={inset || undefined}
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <StateChevron direction="right" />)}
    </Primitive.SubTrigger>
  );
}
export type ContextMenuCheckboxItemProps = React.ComponentProps<
  typeof Primitive.CheckboxItem
> & ItemAdornmentItemProps;
export function ContextMenuCheckboxItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: ContextMenuCheckboxItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.CheckboxItem
      ref={morphRef}
      data-slot="context-menu-checkbox-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="context-menu-item-indicator" data-part="indicator"><AnimatedIcon name="check" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.CheckboxItem>
  );
}
export type ContextMenuRadioItemProps = React.ComponentProps<
  typeof Primitive.RadioItem
> & ItemAdornmentItemProps;
export function ContextMenuRadioItem({
  className,
  adornment,
  adornmentId,
  children,
  ref,
  ...props
}: ContextMenuRadioItemProps) {
  const morphRef = useMorph<HTMLDivElement>("nav", ref);
  return (
    <Primitive.RadioItem
      ref={morphRef}
      data-slot="context-menu-radio-item"
      data-part="item"
      className={cn("v-menu__item", className)}
      {...props}
    >
      {adornItem(children, adornment, adornmentId ?? props.textValue ?? props.id ?? itemText(children), props.asChild, <span className="v-menu__check" aria-hidden="true"><Primitive.ItemIndicator data-slot="context-menu-item-indicator" data-part="indicator"><AnimatedIcon name="dot" preset="validation" /></Primitive.ItemIndicator></span>)}
    </Primitive.RadioItem>
  );
}
export type ContextMenuLabelProps = React.ComponentProps<
  typeof Primitive.Label
>;
export function ContextMenuLabel({
  className,
  ...props
}: ContextMenuLabelProps) {
  return (
    <Primitive.Label
      data-slot="context-menu-label"
      data-part="group"
      className={cn("v-menu__group", className)}
      {...props}
    />
  );
}
export type ContextMenuSeparatorProps = React.ComponentProps<
  typeof Primitive.Separator
>;
export function ContextMenuSeparator({
  className,
  ...props
}: ContextMenuSeparatorProps) {
  return (
    <Primitive.Separator
      data-slot="context-menu-separator"
      data-part="separator"
      className={cn("v-menu__sep", className)}
      {...props}
    />
  );
}
export type ContextMenuShortcutProps = React.ComponentProps<"span">;
export function ContextMenuShortcut({
  className,
  ...props
}: ContextMenuShortcutProps) {
  return (
    <span
      data-slot="context-menu-shortcut"
      className={cn(
        "ml-auto text-[11px] text-[color:var(--muted-foreground)]",
        className,
      )}
      {...props}
    />
  );
}

@layer sahajiv-states {
/* SahaJiv authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-menu__item:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  display: flex;
  align-items: center;
  gap: var(--s-3);
  min-height: 40px;
  padding: 0 var(--s-3);
  border-radius: var(--r-md);
  font-size: var(--fs-control);
  width: 100%;
  text-align: left;
  white-space: nowrap;
}
.v-menu__item:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  ):hover,
.v-menu__item:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  )[data-highlighted] {
  background: var(--v-beige);
}
.v-menu__item:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  ).-danger {
  color: var(--v-danger-ink);
}
.v-menu__sep:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  height: 1px;
  background: var(--v-border);
  margin: 4px 0;
}
.v-menu__group:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted-foreground);
  padding: 8px 12px 4px;
}
.v-menu:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  )::-webkit-scrollbar {
  width: 12px;
  height: 12px;
}
.v-menu:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  )::-webkit-scrollbar-track {
  background: transparent;
  border-radius: 999px;
}
.v-menu:where(
    [data-slot="context-menu"],
    [data-slot^="context-menu-"]
  )::-webkit-scrollbar-thumb {
  background: color-mix(in oklab, var(--v-ink) 34%, transparent);
  border-radius: 999px;
  border: 4px solid transparent;
  background-clip: content-box;
  min-height: 36px;
}
.v-menu:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  scrollbar-gutter: stable;
}
.v-menu:where([data-slot="context-menu"], [data-slot^="context-menu-"]) {
  scrollbar-gutter: stable;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="context-menu"],
  [data-slot^="context-menu-"],
  [data-slot="context-menu"]::before,
  [data-slot="context-menu"]::after,
  [data-slot^="context-menu-"]::before,
  [data-slot^="context-menu-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="context-menu-trigger"]:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}

[data-slot^="context-menu-"][data-inset] {
  padding-left: 32px;
}
[data-slot^="context-menu-"][data-disabled] {
  color: var(--v-disabled-ink);
  cursor: not-allowed;
}
[data-slot^="context-menu-"][data-highlighted] {
  outline: none;
  background: var(--v-beige);
}

[data-slot="context-menu-content"], [data-slot="context-menu-sub-content"] {
 min-width:min(200px,var(--radix-context-menu-content-available-width,calc(100vw - 24px)));
 max-width:min(calc(100vw - 24px),var(--radix-context-menu-content-available-width,calc(100vw - 24px)));
 max-height:min(480px,var(--radix-context-menu-content-available-height,calc(100dvh - 32px)));
 overflow:visible; overscroll-behavior:contain; overflow-wrap:anywhere;
}
[data-slot="context-menu-item"] { min-width:0; height:auto; min-height:36px; white-space:normal; }
[data-slot="context-menu-content"], [data-slot="context-menu-sub-content"] { z-index:var(--z-popover); }
[data-slot^="context-menu-"][data-part="item"] { min-width:0; white-space:normal; overflow-wrap:anywhere; padding-block:8px; }

[data-slot="context-menu-content"], [data-slot="context-menu-sub-content"] { width:var(--menu-width,260px); min-width:min(200px,calc(100vw - 24px)); max-width:calc(100vw - 24px); color:var(--popover-foreground); }
[data-slot^="context-menu-"][data-part="item"] { min-width:0; min-height:44px; padding-block:7px; gap:10px; white-space:normal; overflow-wrap:anywhere; text-align:start; }
[data-slot^="context-menu-"][data-part="item"]:is(:hover,[data-highlighted],[data-state="checked"]) { background:var(--v-beige); color:var(--v-text); }
[data-slot^="context-menu-"][data-part="item"][data-state="checked"], [data-slot^="context-menu-"][data-part="item"]:active { background:var(--v-pink-soft); color:var(--v-text); }
[data-slot^="context-menu-"][data-part="item"].-danger { color:var(--v-danger-ink); }
[data-slot^="context-menu-"][data-part="item"][data-disabled] { background:transparent; color:var(--v-disabled-ink); }
[data-slot^="context-menu-"] .v-menu__check { display:inline-grid; place-items:center; width:18px; min-width:18px; margin-inline-start:auto; color:inherit; }
[data-slot^="context-menu-"] .v-menu__check .v-icon { width:16px; height:16px; }

/* A native flyout may share a narrow viewport with its parent. Use Popper's
   measured free width so its labels wrap instead of leaving the screen. */
[data-slot="context-menu-sub-content"] { min-width:min(200px,var(--radix-context-menu-content-available-width,200px)); max-width:min(calc(100vw - 24px),var(--radix-context-menu-content-available-width,260px)); }

/* The shared ScrollArea owns menu overflow and its custom thumb. */
:is([data-slot="context-menu-content"],[data-slot="context-menu-sub-content"]) .v-list-scroll { --list-scroll-max-height:min(320px, calc(var(--radix-popper-available-height, 60dvh) - 20px)); }

}
